<script lang="ts">
 import Settings from './Settings.svelte';
 import { onMount } from 'svelte';
 import { invoke } from '@tauri-apps/api/core';
 import { listen } from '@tauri-apps/api/event';
 import './styles/management.css';
 type Item={id:string;content:string;done:boolean};
 type Note={id:string;title:string;color:string;visible:boolean;pinned:boolean;count?:number};
 type Rate={day:string;done:number;total:number;bucket:number|null};
 type Stats={week_done:number;week_total:number;week_rate:number;month_done:number;month_total:number;month_rate:number;streak:number};
 let stats=$state<Stats>();
 type Detail={groups:{id:string;title:string;color:string;deleted:boolean;items:Item[]}[];done:number;total:number;editable:boolean};
 let tab=$state(new URLSearchParams(location.search).get('tab')??'notes');
 let notes=$state<Note[]>([]), rates=$state<Rate[]>([]), detail=$state<Detail>();
 let month=$state(''),selected=$state(''),error=$state('');
 const labels={notes:'便签',history:'历史',settings:'设置'};
 const icons={notes:'M15 3H5v18h14V7h-4V3M15 3l4 4',history:'M3 5h18v16H3zM3 10h18M8 2v6M16 2v6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2'};
 const cells=$derived.by(()=>{if(!month)return [];const [y,m]=month.split('-').map(Number);const offset=(new Date(y,m-1,1).getDay()+6)%7;const count=new Date(y,m,0).getDate();return Array.from({length:Math.ceil((offset+count)/7)*7},(_,i)=>i>=offset&&i<offset+count?i-offset+1:0);});
 const heading=$derived(selected?new Date(selected+'T12:00:00').toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'short'}):'');
 async function run(task:()=>Promise<unknown>){try{await task();error='';}catch(e){error=String(e);}}
 async function refresh(){const list=await invoke<Note[]>('list_notes');notes=await Promise.all(list.map(async n=>({...n,count:(await invoke<Item[]>('today_items',{id:n.id})).filter(i=>!i.done).length})));if(month)await refreshHistory();if(selected)detail=await invoke('history_detail',{date:selected});}
 async function refreshHistory(){const requested=month;const [nextRates,nextStats]=await Promise.all([invoke<Rate[]>('history_month',{month:requested}),invoke<Stats>('history_stats',{month:requested})]);if(month===requested){rates=nextRates;stats=nextStats;}}
 async function select(date:string){selected=date;detail=await invoke('history_detail',{date});}
 async function navigate(delta:number){const [y,m]=month.split('-').map(Number);const d=new Date(y,m-1+delta,1);month=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;await refreshHistory();}
 async function toggle(item:Item){await invoke('history_toggle',{date:selected,id:item.id,done:!item.done});await refresh();}
 onMount(()=>{document.documentElement.dataset.theme=new URLSearchParams(location.search).get('theme')??'system';document.body.classList.add('management-body');let disposed=false;const offs:(()=>void)[]=[];run(async()=>{for(const event of ['notes-changed','items-changed','day-changed']){const off=await listen(event,()=>run(refresh));if(disposed)off();else offs.push(off);}const hint=await listen('hide-all-hint',()=>error='便签已暂时隐藏。可通过托盘「显示全部」、面板开关，或全局快捷键恢复。');if(disposed)hint();else offs.push(hint);const off=await listen<string>('panel-tab',e=>tab=e.payload);if(disposed)off();else offs.push(off);const date=await invoke<string>('business_date');month=date.slice(0,7);selected=date;await refresh();});return()=>{disposed=true;offs.forEach(off=>off());document.body.classList.remove('management-body');};});
</script>
<div class="management">
 <nav aria-label="管理面板"><div class="brand"><span class="brand-mark">D</span> DeskNodes</div>{#each Object.entries(labels) as [key,label]}<button class:active={tab===key} onclick={()=>tab=key}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d={icons[key as keyof typeof icons]}/></svg>{label}</button>{/each}<div class="sidebar-foot">留一点空间，给每一天。</div></nav>
 {#if tab==='notes'}<section class="panel-main notes-main"><div class="panel-heading"><h1>便签</h1><button class="new-note" onclick={()=>run(()=>invoke('create_note'))}>＋ 新建</button></div><p class="subtitle">让日常井然有序，也轻盈一点。</p><div class="note-list">{#each notes as n}<article class="note-card" data-color={n.color}><span class="note-swatch"></span><div class="note-description"><h2>{n.title}</h2><p>{n.count} 项未完成</p></div><button class="pin-button" class:pinned={n.pinned} aria-label={`${n.pinned?'取消置顶':'置顶'} ${n.title}`} aria-pressed={n.pinned} onclick={()=>run(()=>invoke('panel_note',{id:n.id,pinned:!n.pinned}))}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="m8 3 8 0-1 6 3 4v2H6v-2l3-4-1-6ZM12 15v7"/></svg></button><button class="visibility" class:on={n.visible} role="switch" aria-checked={n.visible} aria-label={`显示 ${n.title}`} onclick={()=>run(()=>invoke('panel_note',{id:n.id,visible:!n.visible}))}><span></span></button></article>{:else}<div class="empty"><span>＋</span><h2>新建便签</h2><p>从一件小事，开始今天。</p><button class="new-note" onclick={()=>run(()=>invoke('create_note'))}>新建便签</button></div>{/each}</div></section>
 {:else if tab==='history'}<section class="panel-main calendar-pane"><div class="panel-heading"><h1>{month.split('-')[0]} 年 {Number(month.split('-')[1])} 月</h1><button aria-label="上个月" onclick={()=>run(()=>navigate(-1))}>‹</button><button aria-label="下个月" onclick={()=>run(()=>navigate(1))}>›</button></div><div class="history-stats" aria-label="历史统计"><div><span>本周完成率</span><strong>{stats?Math.round(stats.week_rate*100):'—'}<small>%</small></strong><p>完成 {stats?.week_done??0} / {stats?.week_total??0}</p></div><div><span>本月完成率</span><strong>{stats?Math.round(stats.month_rate*100):'—'}<small>%</small></strong><p>完成 {stats?.month_done??0} / {stats?.month_total??0}</p></div><div title="今天全部完成则计入今天，否则从昨天起算；空白或未全部完成的日期会中断连续天数。"><span>连续达成</span><strong>{stats?.streak??'—'}<small>天</small></strong><p>每天，完成一点</p></div></div><div class="calendar">{#each ['一','二','三','四','五','六','日'] as day}<div class="weekday">{day}</div>{/each}{#each cells as day}{@const date=`${month}-${String(day).padStart(2,'0')}`}{@const rate=rates.find(r=>r.day===date)}{#if day}<button class="calendar-day" class:selected={selected===date} data-level={rate?.bucket??'empty'} aria-label={`${date}，${rate?`完成 ${rate.done} / ${rate.total}`:'无事项'}`} aria-pressed={selected===date} onclick={()=>run(()=>select(date))}>{day}</button>{:else}<span></span>{/if}{/each}</div><div class="legend"><span>完成率</span>{#each ['0%','1–49%','50–99%','100%'] as label,i}<span><i data-level={i}></i>{label}</span>{/each}</div></section><aside class="day-detail"><div><div class="detail-heading"><h2>{heading}</h2><span class="read-badge">{detail?.editable?'可补记':'只读'}</span></div><p class="detail-count">完成 {detail?.done??0} / {detail?.total??0}</p></div>{#each detail?.groups??[] as group}<section class="history-group" data-color={group.color}><h3 class:deleted={group.deleted}><i></i>{group.title}{group.deleted?'（已删除）':''}</h3>{#each group.items as item}<button class="history-item" class:completed={item.done} disabled={!detail?.editable} aria-label={`${item.done?'标为未完成':'标为完成'}：${item.content}`} aria-pressed={item.done} onclick={()=>run(()=>toggle(item))}><span class="history-check">{item.done?'✓':''}</span><span>{item.content}</span></button>{/each}</section>{/each}{#if detail?.total===0}<div class="day-empty">这一天，留白也很好。<p>暂无事项</p></div>{/if}{#if detail?.editable}<p class="edit-hint">可补记上一业务日的完成情况。完成后，今天的顺延事项会自动移除。</p>{/if}</aside>
 {:else}<Settings />{/if}
 {#if error}<div class="panel-error" role="alert">{error}<button onclick={()=>error=''} aria-label="关闭错误">×</button></div>{/if}
</div>
